#!/usr/bin/env node
/**
 * Copies the templates the generator fills in into generator/src/templates.js, so the same
 * generator runs in a browser (elvira.digital/deploy), where it cannot read files.
 * `npm test` fails when the copy is out of date: run `npm run bundle` after editing a template.
 */
import {readFileSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import path from 'node:path';

export const SOURCES = ['.env.example', 'nginx/catalog.conf.tmpl', 'nginx/portal.conf.tmpl', 'readium/config.yaml.tmpl'];

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const target = path.join(root, 'generator/src/templates.js');

export function bundle() {
  const entries = SOURCES.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(path.join(root, f), 'utf8'))},`);
  return `// Generated by generator/bundle.js from ${SOURCES.join(', ')}. Do not edit: npm run bundle.\nexport const TEMPLATES = {\n${entries.join('\n')}\n};\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(target, bundle());
  console.log(`bundle: ${SOURCES.length} templates -> generator/src/templates.js`);
}
